// List the configured channel IDs and emit one item per channel.
// Read the seen-video state for each so the downstream filter can compare.

const raw = $env.YOUTUBE_CHANNEL_IDS || '';
const channelIds = raw.split(',').map(s => s.trim()).filter(Boolean);
if (channelIds.length === 0) {
  throw new Error('YOUTUBE_CHANNEL_IDS env is empty. Set it to a comma-separated list of UC... channel IDs.');
}
// Cap at 50 channels per run to keep one execution bounded.
if (channelIds.length > 50) {
  throw new Error('YOUTUBE_CHANNEL_IDS exceeds 50 channels. Split across multiple workflow instances if you need more.');
}

const data = $getWorkflowStaticData('global');
data.seenVideos = data.seenVideos || {};
const seen = data.seenVideos;

return channelIds.map(id => ({ json: {
  channelId: id,
  rssUrl: 'https://www.youtube.com/feeds/videos.xml?channel_id=' + id,
  seenForChannel: Object.keys(seen).filter(k => seen[k] && seen[k].channelId === id).map(k => k),
}}));

// Per-host sliding-window rate limit on the RSS fetch + Notion write side, opt-in.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT_PER_HOUR = 30;
const WINDOW_MS = 60 * 60 * 1000;
const MAX_KEYS = 5000;

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const key = 'host:youtube.com';
  const hits = buckets[key] || [];
  if (hits.length >= LIMIT_PER_HOUR) {
    out.push({ json: { ...j, skipped: true, reason: 'rate-limit-host' } });
    continue;
  }
  buckets[key] = [...hits, now];
  out.push(item);
}
return out;

// Lightweight RSS / Atom parser for YouTube feeds.
// Each YouTube RSS entry has yt:videoId, yt:channelId, title, link, published, description (optional), media:thumbnail.
//
// Extracted via regex against the raw XML rather than pulling in a full XML parser.
// YouTube's feed is well-formed and does not need that level of robustness.

const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  const xml = (j.data && typeof j.data === 'string') ? j.data : (j.body && typeof j.body === 'string' ? j.body : '');
  if (!xml) {
    out.push({ json: { ...j, skipped: true, reason: 'rss-empty' } });
    continue;
  }
  const channelId = j.channelId;

  // Pull entries.
  const entries = [];
  const entryRe = /<entry>([\s\S]*?)<\/entry>/g;
  let match;
  while ((match = entryRe.exec(xml)) !== null) {
    const body = match[1];
    const videoId = (body.match(/<yt:videoId>([^<]+)<\/yt:videoId>/) || [])[1];
    if (!videoId) continue;
    const title = ((body.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || '').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
    const link = (body.match(/<link rel="alternate" href="([^"]+)"/) || [])[1] || ('https://www.youtube.com/watch?v=' + videoId);
    const published = (body.match(/<published>([^<]+)<\/published>/) || [])[1] || null;
    const description = ((body.match(/<media:description>([\s\S]*?)<\/media:description>/) || [])[1] || '').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
    const thumbnail = (body.match(/<media:thumbnail url="([^"]+)"/) || [])[1] || null;
    const author = ((body.match(/<author>[\s\S]*?<name>([^<]+)<\/name>/) || [])[1] || '').trim();

    entries.push({
      channelId,
      videoId,
      title: title.slice(0, 200),
      url: link,
      publishedAt: published,
      description: description.slice(0, 1800),
      thumbnail,
      author: author.slice(0, 100),
    });
  }

  // YouTube returns most recent first. Keep that order.
  for (const e of entries) {
    out.push({ json: e });
  }
}
if (out.length === 0) {
  return [{ json: { skipped: true, reason: 'no-entries-parsed' } }];
}
return out;

// Idempotency on videoId, opt-in. Persistent across runs (long-lived workflow static data).
// Plus per-channel cap on how many videos to process in one run.

const MAX_PER_CHANNEL = parseInt($env.MAX_VIDEOS_PER_CHANNEL_PER_RUN || '10', 10);
const items = $input.all();
const out = [];

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  // No idempotency, just enforce the per-channel cap.
  const perChannel = {};
  for (const item of items) {
    const j = item.json || {};
    if (j.skipped) { out.push(item); continue; }
    const id = j.channelId;
    perChannel[id] = (perChannel[id] || 0) + 1;
    if (perChannel[id] > MAX_PER_CHANNEL) continue;
    out.push(item);
  }
  return out;
}

const data = $getWorkflowStaticData('global');
data.seenVideos = data.seenVideos || {};
const seen = data.seenVideos;
const now = Date.now();
const MAX_KEYS = 50000;
const KEEP_DAYS = 90; // remember a videoId for 90 days, then evict

for (const k of Object.keys(seen)) {
  if (now - (seen[k].seenAt || 0) > KEEP_DAYS * 24 * 60 * 60 * 1000) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => (a[1].seenAt || 0) - (b[1].seenAt || 0)).slice(0, 5000);
  for (const [k] of oldest) delete seen[k];
}

const perChannel = {};
for (const item of items) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }
  const id = j.channelId;
  const vid = j.videoId;
  if (!vid) continue;
  if (seen[vid]) continue; // already processed
  perChannel[id] = (perChannel[id] || 0) + 1;
  if (perChannel[id] > MAX_PER_CHANNEL) continue; // cap
  seen[vid] = { channelId: id, seenAt: now };
  out.push(item);
}
if (out.length === 0) {
  return [{ json: { skipped: true, reason: 'no-new-videos' } }];
}
return out;

// Build the LLM summary prompt if LLM_SUMMARY_ENABLED=1, else mark items as no-summary-needed.

const summaryEnabled = $env.LLM_SUMMARY_ENABLED === '1';
const provider = ($env.LLM_PROVIDER || 'openai').toLowerCase();

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }
  if (!summaryEnabled) {
    out.push({ json: { ...j, summary: null, summaryProvider: 'none' } });
    continue;
  }

  const sourceText = (j.title + '\n\n' + (j.description || '')).slice(0, 3000);
  const systemPrompt = 'Summarize the following YouTube video in 2-3 short sentences. Output ONLY the summary, no preamble. If the description is empty or too short to summarize, return the title verbatim.';
  out.push({ json: { ...j, provider, systemPrompt, userText: sourceText } });
}
return out;

// Normalize OpenAI vs Anthropic response shape and merge with the upstream video metadata.
// Items can come from openai-success, anthropic-success, no-summary, or LLM-error path.
//
// Metadata-lookup priority (catches the partial-LLM-failure case):
// 1. pairedItem index against $('Build Summary Prompt').all(): n8n's stable item-tracking
//    across branches (works even when only a subset of items hit the error pin).
// 2. In-place $json.videoId: true for the no-summary branch which passes metadata through.
// 3. Last-resort array-index match: only used when pairedItem missing and $json has no videoId.
//    This is the legacy fallback that the Critic flagged as fragile, kept here as a final
//    safety net rather than the primary path.

const items = $input.all();
let upstream = [];
try { upstream = $('Build Summary Prompt').all(); } catch (e) { upstream = []; }

const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }

  let summary = null;
  if (j.choices && Array.isArray(j.choices) && j.choices.length > 0) {
    summary = (j.choices[0].message && j.choices[0].message.content) || '';
  } else if (j.content && Array.isArray(j.content) && j.content.length > 0) {
    summary = j.content[0].text || '';
  } else if (j.summary !== undefined) {
    summary = j.summary;
  }
  if (typeof summary === 'string') summary = summary.trim().slice(0, 1000);

  let videoMeta = null;

  // Tier 1: pairedItem (preserves order across branches and error paths)
  if (item.pairedItem) {
    const pIdx = typeof item.pairedItem === 'object'
      ? (item.pairedItem.item != null ? item.pairedItem.item : null)
      : (typeof item.pairedItem === 'number' ? item.pairedItem : null);
    if (typeof pIdx === 'number' && upstream[pIdx] && upstream[pIdx].json && upstream[pIdx].json.videoId) {
      videoMeta = upstream[pIdx].json;
    }
  }

  // Tier 2: in-place metadata (no-summary branch path)
  if (!videoMeta && j.videoId) {
    videoMeta = j;
  }

  // Tier 3: last-resort array-index match (legacy fallback, fragile across error pins)
  if (!videoMeta && upstream[i] && upstream[i].json && upstream[i].json.videoId) {
    videoMeta = upstream[i].json;
  }

  // Fail-safe: if nothing matched, drop with structured warning rather than write garbage to Notion.
  if (!videoMeta || !videoMeta.videoId) {
    out.push({ json: { skipped: true, reason: 'metadata-lookup-failed', summary } });
    continue;
  }

  out.push({ json: {
    skipped: false,
    channelId: videoMeta.channelId,
    videoId: videoMeta.videoId,
    title: videoMeta.title,
    url: videoMeta.url,
    publishedAt: videoMeta.publishedAt,
    description: videoMeta.description,
    thumbnail: videoMeta.thumbnail,
    author: videoMeta.author,
    summary,
  }});
}
return out;

// Fallback for any failure (RSS fetch, LLM, Notion).
// Build a structured error log and post a Slack alert if SLACK_OPS_WEBHOOK is set.

const input = $input.first();
const raw = input.json || {};
const errorRaw = raw.error || raw;
const isLlmError = !!(errorRaw && (errorRaw.message || errorRaw.code || (errorRaw.error && errorRaw.error.message)));
let errorMessage;
if (isLlmError) {
  errorMessage = (errorRaw.message) || (errorRaw.error && errorRaw.error.message) || ('Error code ' + (errorRaw.code || '?'));
} else {
  errorMessage = 'Unknown error in YouTube-to-Notion sync';
}

let stage = 'unknown';
try { if ($('Notion Create Page').first()) stage = 'notion'; } catch (e) {}
try { if ($('OpenAI Summarize').first()) stage = 'openai'; } catch (e) {}
try { if ($('Anthropic Summarize').first()) stage = 'anthropic'; } catch (e) {}
try { if ($('Fetch YouTube RSS').first()) stage = 'rss-fetch'; } catch (e) {}

return [{ json: { syncError: { message: errorMessage, stage, raw: errorRaw } } }];
